const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const ethi = ee.FeatureCollection('FAO/GAUL/2015/level0')
      .filter(ee.Filter.eq('ADM0_NAME', 'Ethiopia'))
      .geometry();
    const latImg = ee.Image.pixelLonLat().select('latitude');
    const midLat = ethi.centroid(1).coordinates().get(1);
    const countryMask = ee.Image.constant(1).clip(ethi).gt(0);
    const start2021 = '2021-10-01';
    const end2021 = '2021-12-01';
    const baseStart = '2000-10-01';
    const baseEnd = '2013-12-01';
    const scale = 5500;

    // 2. Data Acquisition & Check
    const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

    const col2021 = chirps.filterDate(start2021, end2021).filterBounds(ethi);
    const n2021 = col2021.size().getInfo();
    if (n2021 === 0) {
      console.log('2021 Images: 0');
      console.log('C1');
      return;
    }

    const colBaseline = chirps.filterDate(baseStart, baseEnd).filterBounds(ethi);
    const nBaseImgs = colBaseline.size().getInfo();
    if (nBaseImgs === 0) {
      console.log('Baseline Images (2000-2013 Oct-Nov): 0');
      console.log('C1');
      return;
    }

    const years = ee.List.sequence(2000, 2013);
    const yearlySums = ee.ImageCollection(years.map(function(y) {
      y = ee.Number(y);
      const sumY = chirps
        .filterDate(ee.Date.fromYMD(y, 10, 1), ee.Date.fromYMD(y, 12, 1))
        .filterBounds(ethi)
        .sum()
        .rename('precip');
      return sumY.set('year', y);
    }));
    const baselineMeanImg = yearlySums.mean().rename('precip');
    const sum2021Img = col2021.sum().rename('precip');

    // 3. Processing: masks and pixel counts
    const northMask = countryMask.and(latImg.gt(midLat));
    const southMask = countryMask.and(latImg.lte(midLat));

    const sum2021North = sum2021Img.updateMask(northMask);
    const sum2021South = sum2021Img.updateMask(southMask);
    const baseNorth = baselineMeanImg.updateMask(northMask);
    const baseSouth = baselineMeanImg.updateMask(southMask);

    const count2021North = sum2021North.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: ethi,
      scale: scale,
      maxPixels: 1e13
    }).get('precip').getInfo();
    const count2021South = sum2021South.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: ethi,
      scale: scale,
      maxPixels: 1e13
    }).get('precip').getInfo();

    if (!count2021North || !count2021South || count2021North === 0 || count2021South === 0) {
      console.log(`Valid pixels 2021 (north/south): ${count2021North || 0} / ${count2021South || 0}`);
      console.log('C2');
      return;
    }

    // 4. Calculation: area-summed totals and anomalies
    const sum2021NorthTot = sum2021North.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: ethi,
      scale: scale,
      maxPixels: 1e13
    }).get('precip').getInfo();
    const sum2021SouthTot = sum2021South.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: ethi,
      scale: scale,
      maxPixels: 1e13
    }).get('precip').getInfo();
    const baseNorthTot = baseNorth.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: ethi,
      scale: scale,
      maxPixels: 1e13
    }).get('precip').getInfo();
    const baseSouthTot = baseSouth.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: ethi,
      scale: scale,
      maxPixels: 1e13
    }).get('precip').getInfo();

    const nums = [sum2021NorthTot, sum2021SouthTot, baseNorthTot, baseSouthTot];
    const invalid = nums.some(v => v === null || v === undefined || !isFinite(v));
    if (invalid || baseNorthTot <= 0 || baseSouthTot <= 0) {
      console.log('Calculation invalid (null/NaN or baseline<=0).');
      console.log('C3');
      return;
    }

    const anomN = sum2021NorthTot - baseNorthTot;
    const anomS = sum2021SouthTot - baseSouthTot;
    const pctN = (sum2021NorthTot / baseNorthTot - 1) * 100.0;
    const pctS = (sum2021SouthTot / baseSouthTot - 1) * 100.0;

    // 5. Evidence prints (<=20 lines)
    console.log(`CHIRPS Oct-Nov 2021 images: ${n2021}`);
    console.log(`Baseline years (2000-2013): ${years.size().getInfo()} | Daily imgs: ${nBaseImgs}`);
    console.log(`Valid pixels 2021 (north/south): ${count2021North} / ${count2021South}`);
    console.log(`North: 2021 total(mm)=${sum2021NorthTot.toFixed(0)}, Clim mean(mm)=${baseNorthTot.toFixed(0)}, Anom(mm)=${anomN.toFixed(0)}, Anom(%)=${pctN.toFixed(1)}`);
    console.log(`South: 2021 total(mm)=${sum2021SouthTot.toFixed(0)}, Clim mean(mm)=${baseSouthTot.toFixed(0)}, Anom(mm)=${anomS.toFixed(0)}, Anom(%)=${pctS.toFixed(1)}`);

    // 6. Final Answer
    // Question: Did southern Ethiopia receive less rainfall than northern Ethiopia relative to its long-term average?
    // Interpretation: Yes if anomaly_south < anomaly_north (more negative).
    const answer = (anomS < anomN) ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
